package com.bobfull.admin.controller;
import com.bobfull.admin.dto.*; import com.bobfull.admin.service.AdminModerationReportService; import com.bobfull.chat.domain.entity.ReportStatus; import com.bobfull.common.response.*; import com.bobfull.auth.application.model.AuthMember; import jakarta.validation.Valid; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/moderation/reports") public class AdminModerationReportController { private final AdminModerationReportService service; public AdminModerationReportController(AdminModerationReportService service){this.service=service;} @GetMapping public ApiResponse<PageResponse<AdminModerationReportResponse>> list(@RequestParam(required=false) ReportStatus status,@PageableDefault(size=20) Pageable pageable){return ApiResponse.success(service.list(status,pageable));} @GetMapping("/{reportId}") public ApiResponse<AdminModerationReportDetailResponse> get(@PathVariable Long reportId){return ApiResponse.success(service.get(reportId));} @PatchMapping("/{reportId}/review") public ApiResponse<AdminModerationReportResponse> review(@AuthenticationPrincipal AuthMember admin,@PathVariable Long reportId,@Valid @RequestBody AdminReportReviewRequest request){return ApiResponse.success(service.review(reportId,admin.id(),request));} }
